import { useState, useEffect } from "react";
import axios from "axios";
import { T, LEVELS, statusConfig, levelColors } from "./constants";
import Sidebar from "./Sidebar";
import ApplicationModal from "./ApplicationModal";

/**
 * AdminDashboard
 */
export default function AdminDashboard({ onLogout }) {
  const [apps, setApps] = useState([]);
  const [activeBranch, setActiveBranch] = useState("cairo");
  const [activeLevel, setActiveLevel] = useState("HSK 1");
  const [search, setSearch] = useState("");
  const [selectedApp, setSelectedApp] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // ── Fetch students from backend ─────────────────────────
  const fetchStudents = async () => {
    try {
      const response = await axios.get("http://localhost:8000/students");

      const formatted = response.data.map((s) => ({
        id: s.id,
        name: s.name,
        nid: s.national_id,
        phone: s.phone,
        email: s.email,
        level: s.level?.toUpperCase().replace("HSK", "HSK ").trim(),
        branch: s.location?.toLowerCase().includes("cairo")
          ? "cairo"
          : "ainshams",
        mode: s.mode,
        date: new Date(s.created_at).toLocaleDateString(),
        status: s.status || "pending",
      }));
      console.log("Fetched students:", formatted);

      setApps(formatted);
    } catch (err) {
      console.error("Fetch error:", err);
      setError("فشل تحميل البيانات");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // ── Derived data ────────────────────────────────────────
  const levelApps = apps.filter(
    (a) =>
      a.branch === activeBranch &&
      a.level?.toLowerCase().includes(activeLevel.toLowerCase())
  );

  const filtered = search
    ? levelApps.filter(
      (a) =>
        a.name.includes(search) ||
        a.phone.includes(search) ||
        a.email.toLowerCase().includes(search.toLowerCase()) ||
        a.nid.includes(search)
    )
    : levelApps;

  const stats = {
    total: apps.length,
    pending: apps.filter((a) => a.status === "pending").length,
    approved: apps.filter((a) => a.status === "approved").length,
    rejected: apps.filter((a) => a.status === "rejected").length,
  };

  const branchLabel =
    activeBranch === "cairo" ? "جامعة القاهرة" : "جامعة عين شمس";

  // ── Handlers ───────────────────────────────────────────
  const handleBranch = (key) => {
    setActiveBranch(key);
    setActiveLevel("HSK 1");
    setSearch("");
  };

  const handleLevel = (lv) => {
    setActiveLevel(lv);
    setSearch("");
  };

  const changeStatus = (id, status) => {
    setApps((prev) =>
      prev.map((a) => (a.id === id ? { ...a, status } : a))
    );
    setSelectedApp((prev) =>
      prev?.id === id ? { ...prev, status } : prev
    );
  };

  // ── Loading / Error UI ─────────────────────────────────
  if (loading) {
    return <div style={{ padding: "40px" }}>⏳ جاري التحميل...</div>;
  }

  if (error) {
    return <div style={{ padding: "40px", color: "red" }}>{error}</div>;
  }

  // ── Styles (UNCHANGED) ─────────────────────────────────
  const s = {
    root: {
      display: "flex",
      minHeight: "100vh",
      fontFamily: "'Cairo', sans-serif",
      direction: "rtl",
      background: T.bg,
    },
    main: { flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" },

    topbar: {
      background: "#fff",
      borderBottom: `1px solid ${T.border}`,
      padding: "0 28px",
      height: "60px",
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      boxShadow: T.shadowSm,
      flexShrink: 0,
    },
    topbarLeft: { display: "flex", alignItems: "center", gap: "14px" },
    menuBtn: {
      background: "none",
      border: "none",
      cursor: "pointer",
      fontSize: "20px",
      color: T.inkSoft,
      padding: "4px",
    },
    breadcrumb: {
      fontSize: "14px",
      color: T.inkSoft,
      display: "flex",
      alignItems: "center",
      gap: "6px",
    },
    breadActive: { fontWeight: 700, color: T.red },
    breadMuted: { fontWeight: 400, color: T.muted },
    adminTag: { fontSize: "13px", color: T.muted },

    content: { flex: 1, padding: "28px", overflowY: "auto" },

    statsRow: {
      display: "grid",
      gridTemplateColumns: "repeat(4, 1fr)",
      gap: "16px",
      marginBottom: "28px",
    },
    statCard: (color) => ({
      background: "#fff",
      border: `1px solid ${T.border}`,
      borderRadius: "14px",
      padding: "20px 22px",
      boxShadow: T.shadowSm,
      borderTop: `3px solid ${color}`,
    }),
    statNum: (color) => ({
      fontSize: "32px",
      fontWeight: 900,
      color,
      marginBottom: "4px",
    }),
    statLabel: { fontSize: "12px", color: T.muted },

    tableCard: {
      background: "#fff",
      borderRadius: "16px",
      border: `1px solid ${T.border}`,
      boxShadow: T.shadowSm,
      overflow: "hidden",
    },
    tableHeader: {
      padding: "18px 22px",
      display: "flex",
      justifyContent: "space-between",
      borderBottom: `1px solid ${T.border}`,
    },
    searchInput: {
      padding: "9px 14px",
      border: `1.5px solid ${T.border}`,
      borderRadius: "8px",
      width: "220px",
    },
    table: { width: "100%", borderCollapse: "collapse" },
    th: {
      padding: "12px",
      background: "#FAFAF8",
      textAlign: "right",
    },
    td: { padding: "12px" },
    statusBadge: (status) => ({
      padding: "4px 12px",
      borderRadius: "6px",
      background: statusConfig[status]?.bg,
      color: statusConfig[status]?.color,
    }),
    empty: {
      padding: "60px",
      textAlign: "center",
      color: T.muted,
    },
  };

  const TABLE_HEADERS = [
    "#",
    "الاسم",
    "الهاتف",
    "البريد الإلكتروني",
    "طريقة الدراسة",
    "تاريخ التسجيل",
    "الحالة",
  ];

  const STAT_CARDS = [
    { num: stats.total, label: "إجمالي الطلبات", color: T.red },
    { num: stats.pending, label: "قيد المراجعة", color: "#F57F17" },
    { num: stats.approved, label: "مقبول", color: "#2E7D32" },
    { num: stats.rejected, label: "مرفوض", color: T.red },
  ];

  // ── Render ────────────────────────────────────────────
  return (
    <div style={s.root}>
      <Sidebar
        apps={apps}
        activeBranch={activeBranch}
        activeLevel={activeLevel}
        onBranch={handleBranch}
        onLevel={handleLevel}
        onLogout={onLogout}
        open={sidebarOpen}
      />

      <div style={s.main}>
        <div style={s.topbar}>
          <div style={s.topbarLeft}>
            <button style={s.menuBtn} onClick={() => setSidebarOpen((p) => !p)}>☰</button>
            <div style={s.breadcrumb}>
              <span>لوحة التحكم › {branchLabel} › {activeLevel}</span>
            </div>
          </div>
          <div style={s.adminTag}>👤 مسؤول النظام</div>
        </div>

        <div style={s.content}>
          <div style={s.statsRow}>
            {STAT_CARDS.map((st, i) => (
              <div key={i} style={s.statCard(st.color)}>
                <div style={s.statNum(st.color)}>{st.num}</div>
                <div style={s.statLabel}>{st.label}</div>
              </div>
            ))}
          </div>

          <div style={s.tableCard}>
            <div style={s.tableHeader}>
              <input
                style={s.searchInput}
                placeholder="بحث..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            {filtered.length === 0 ? (
              <div style={s.empty}>لا توجد بيانات</div>
            ) : (
              <table style={s.table}>
                <thead>
                  <tr>
                    {TABLE_HEADERS.map((h) => (
                      <th key={h} style={s.th}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((app, idx) => (
                    <tr key={app.id} onClick={() => setSelectedApp(app)}>
                      <td style={s.td}>{idx + 1}</td>

                      {/* FIXED */}
                      <td style={s.td}>{app.name}</td>

                      {/* FIXED field name */}
                      <td style={s.td}>{app.nid}</td>

                      <td style={s.td}>{app.phone}</td>
                      <td style={s.td}>{app.email}</td>
                      <td style={s.td}>{app.mode}</td>
                      <td style={s.td}>{app.date}</td>

                      <td style={s.td}>
                        <span style={s.statusBadge(app.status)}>
                          {statusConfig[app.status]?.label}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </div>

      <ApplicationModal
        app={selectedApp}
        onClose={() => setSelectedApp(null)}
        onStatusChange={changeStatus}
      />
    </div>
  );
}
